/** The four learn methods, in the order the tables print them. Same order as MOVE_TABS. */
export const MOVE_LEARN_METHODS = ['level', 'machine', 'egg', 'tutor'];

/** The four learn methods with their 繁體中文 labels, for pages that need them standalone. */
export const MOVE_LEARN_METHODS_ZH = {
  level: '等級提升',
  machine: '招式學習器',
  egg: '遺傳招式',
  tutor: '傳授招式'
};

/**
 * A move's effect provenance. `moves_zh.json` rows carry `effectSource`, and a
 * page that renders the sentence has no business claiming where it came from —
 * but the 93 converted rows ARE a conversion, and a reader comparing 起風's
 * wording against InfoPoke's 刮起狂風 deserves to know which one was edited.
 */
export const MOVE_EFFECT_SOURCE_ZH = {
  'pokeapi-zh-hant': 'PokeAPI 繁體原文',
  'infopoke-s2twp': 'InfoPoke 簡轉繁'
};

/** The URL for a move's own page. §3.A: the one place this shape is assembled. */
export function moveUrl(move) {
  const en = typeof move === 'object' && move !== null ? move.en : move;
  return `move.html?move=${encodeURIComponent(en)}`;
}

/** Move id (number or numeric string) -> the row, or null. */
export function moveById(moves, id) {
  return moves[String(id)] || null;
}

/**
 * Does any Pokémon learn this move?
 *
 * Takes the counts file rather than the row, because `moves_zh.json` already
 * carries `learners` and a caller that had it would not ask. It exists for the
 * list page, which needs the answer while building every row and would otherwise
 * read the same number 919 times.
 */
export function moveHasLearners(counts, id) {
  const row = counts[String(id)];
  if (!row) return false;
  return row.total > 0;
}

/** Does any Pokémon learn this move, using moves_zh.json's own denormalised count. */
export function moveIsLearnable(move) {
  return typeof move?.learners === 'number' && move.learners > 0;
}

/**
 * A searchable haystack for one move: 繁中名, English name, id, and the target
 * and ailment labels, so typing 「對手全體」 or 「麻痺」 finds the move as
 * readily as typing 拍擊. Built once per row by the list page, not per keystroke.
 */
export function moveSearchText(move) {
  const id = Number(move.id);
  return [
    move.zh,
    move.en,
    `#${id}`,
    String(id),
    MOVE_TARGET_ZH[move.target] || '',
    MOVE_AILMENT_ZH[move.ailment] || '',
    MOVE_CATEGORY_ZH[move.category] || ''
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
}

/** Numbers render as a dash when the move has none; 0 is a real value and must not join them. */
export function moveNumber(value) {
  return value === null || value === undefined ? '—' : String(value);
}

/**
 * 命中 as a label rather than a percentage.
 *
 * `accuracy: 0` is 必中, not 「0%」. Three moves carry it and one of them says so
 * in its own effect text (迅子利刃: 「必定命中」), so rendering the raw number
 * would print a statement the page's own data contradicts two lines below.
 */
export function moveAccuracyText(accuracy) {
  if (accuracy === 0) return '必中';
  return accuracy === null || accuracy === undefined ? '—' : `${accuracy}%`;
}

/**
 * 威力, with the one move whose 0 is a number rather than an absence.
 *
 * 16 status moves carry `power: 0` where null would read the same, and 硬壓
 * carries 0 as a real value — its power scales with the target's remaining HP
 * from 0 to 100. The data keeps both because they are different facts; the label
 * is where they are reconciled, and it is the only place that can be, because
 * only the label knows what the move does.
 */
export function movePowerText(move) {
  if (move.power === 0 && move.class !== 'status') return '依對手剩餘 HP 變化';
  // A status move's `power: 0` means "no power", so it dashes like the null.
  // Rendering it as 0 would print a number for a value the column has no use
  // for, next to 硬壓's 0 which is a real one.
  if (move.power === 0) return '—';
  return moveNumber(move.power);
}

/**
 * 「2～5 次」 / 「至少 2 次」 / 「—」 for a [min, max] pair.
 *
 * A null max with a non-null min means "at least N", which is a different claim
 * from "N" — 連環巴掌 hits 2–5 times and 居合斬 hits at least once more — so the
 * two halves are formatted separately rather than by picking one number.
 */
export function movePairText(pair, unit = '') {
  if (!pair || !Array.isArray(pair)) return '—';
  const [min, max] = pair;
  if (min !== null && max !== null) return `${min}～${max}${unit}`;
  if (min !== null) return `至少 ${min}${unit}`;
  if (max !== null) return `最多 ${max}${unit}`;
  return '—';
}

/** 先制: PokeAPI's signed priority, as a label rather than a bare integer. */
export function movePriorityText(priority) {
  if (!priority) return '0';
  return priority > 0 ? `+${priority}` : String(priority);
}

/**
 * Split `moves_zh.json` into its rows and its provenance record.
 *
 * Every consumer that iterates the file needs this, and a page that forgets the
 * `_meta` key renders a "move" called `_meta` — which is a row with no `zh`, no
 * `power` and no `type`, so it looks like a layout bug rather than an iteration
 * bug. One function so that mistake has one place to be made.
 */
export function moveRows(moves) {
  return Object.entries(moves)
    .filter(([key]) => key !== '_meta')
    .map(([id, move]) => ({ id: Number(id), ...move }));
}

/* ===== loaders ===== */

const jsonCache = new Map();

async function loadJson(name) {
  if (jsonCache.has(name)) return jsonCache.get(name);
  const pending = fetch(`assets/data/${name}`).then(response => {
    if (!response.ok) {
      throw new Error(`${name} -> HTTP ${response.status}`);
    }
    return response.json();
  });
  jsonCache.set(name, pending);
  return pending;
}

/** The 919-move table. */
export function loadMoves() {
  return loadJson('moves_zh.json');
}

/** move id → the Pokémon that learn it. 409 KB; `move.html` only. */
export function loadMoveLearners() {
  return loadJson('move_learners.json');
}

/** move id → how many Pokémon learn it, per method. 40 KB; `moves.html` only. */
export function loadMoveLearnersCount() {
  return loadJson('move_learners_count.json');
}

/* ===== queries ===== */

/**
 * Filter the 919 rows.
 *
 * Every predicate is optional and they AND together. `q` matches against
 * `moveSearchText`, so it is a caller-supplied precomputed string rather than
 * something computed per keystroke for 919 rows — the query runs on every
 * keystroke and building the haystack inside it would rebuild 919 strings per
 * character typed.
 *
 * `learnable` is a filter rather than a default because 「誰能學這招」 is a
 * question the group-builder will ask constantly, and making it a chip means the
 * answer is one click rather than a special mode.
 */
export function filterMoves(rows, { q = '', type = null, cls = null, generation = null, learnable = null } = {}) {
  const needle = q.trim().toLowerCase();
  return rows.filter(move => {
    if (needle && !move.haystack.includes(needle)) return false;
    if (type && move.type !== type) return false;
    if (cls && move.class !== cls) return false;
    if (generation && move.generation !== generation) return false;
    if (learnable === true && !moveIsLearnable(move)) return false;
    if (learnable === false && moveIsLearnable(move)) return false;
    return true;
  });
}

/** Rows with their search haystack attached, so filterMoves can be called per keystroke. */
export function prepareMoves(moves) {
  return moveRows(moves).map(move => ({ ...move, haystack: moveSearchText(move) }));
}